target.css:
:root {
  --ink: #24313a;
  --muted: #66747d;
  --paper: #fffdf7;
  --line: #d9e0dc;
  --mint: #dff1e6;
  --mint-ink: #24704d;
  --coral: #ef6b5a;
  --navy: #24495d;
}

.bout-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.event-mark {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mark-icon {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 10px;
  background: var(--mint);
  font-size: 18px;
}

.eyebrow,
.strip-info p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h2 {
  margin: 2px 0 0;
  font-size: 18px;
  line-height: 1.15;
}

.live-badge {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--coral);
  color: var(--paper);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.bout-body {
  display: grid;
  grid-template-columns: 1fr 112px;
  min-height: 112px;
}

.fencers {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 6px;
  padding: 12px 16px;
}

.fencer {
  display: flex;
  align-items: center;
  gap: 9px;
}

.seed {
  display: grid;
  width: 26px;
  height: 26px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--navy);
  font-size: 11px;
  font-weight: 800;
}

.fencer strong,
.fencer small {
  display: block;
}

.fencer strong {
  font-size: 14px;
  line-height: 1.1;
}

.fencer small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 11px;
}

.versus {
  margin-left: 8px;
  color: var(--coral);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.strip-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  padding: 12px;
  border-left: 1px solid var(--line);
  background: var(--mint);
}

.strip-info strong {
  color: var(--mint-ink);
  font-size: 17px;
  line-height: 1;
}

.strip-info span {
  color: var(--mint-ink);
  font-size: 10px;
  line-height: 1.25;
}

.card-footer {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.card-footer button {
  margin-left: auto;
  padding: 6px 10px;
  border: 0;
  border-radius: 7px;
  background: var(--navy);
  color: var(--paper);
  font-size: 11px;
  font-weight: 700;
}

